INSERT INTO feature VALUES('unit-source-identifiers','workflow','A unit accounts for the design pages that name it',NULL,'implemented','ordinary',NULL,'A unit''s `## Sources` names each design page of the vault that names one of the unit''s identifiers: its number, the numbers of its `from:` line and of its epic, and each ledger row that it names in backquotes. A level-two section that names one gives its page and each design page that it links, and a crate that the unit names gives its own page. `unit:check` refuses a unit whose `## Sources` lacks such a page, and a `not read` row with its reason admits one. A unit signed before the rule gets a note, and a host with no vault refuses nothing.',NULL,'.config/bodies/identifiers.json',NULL,NULL);
